PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE tl (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nome TEXT NOT NULL,
  competenze TEXT
);
CREATE TABLE val (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nome TEXT NOT NULL,
  competenze TEXT
, cognome TEXT, sa INTEGER CHECK (sa IN (0, 1)), ss INTEGER CHECK (ss IN (0, 1)), ulss_id INTEGER REFERENCES ulss(id), sede_rif_id INTEGER REFERENCES "sedi"(id), esterno INTEGER NOT NULL DEFAULT 0 CHECK (esterno IN (0, 1)));
CREATE TABLE au (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nome_sede TEXT NOT NULL,
  competenze_richieste TEXT,
  data TEXT NOT NULL,
  ora_inizio INTEGER NOT NULL,
  ora_fine INTEGER NOT NULL,
  numero_valutatori INTEGER NOT NULL,
  team_leader_id INTEGER REFERENCES tl(id)
, sede_campo TEXT, team_leader_campo TEXT, data_scadenza TEXT, confermata INTEGER NOT NULL DEFAULT 0 CHECK (confermata IN (0, 1)));
CREATE TABLE ac (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nome_sede TEXT NOT NULL,
  competenze_richieste TEXT,
  data TEXT NOT NULL,
  ora_inizio INTEGER NOT NULL,
  ora_fine INTEGER NOT NULL,
  numero_valutatori INTEGER NOT NULL,
  team_leader_id INTEGER REFERENCES tl(id)
, sede_campo TEXT, team_leader_campo TEXT, data_scadenza TEXT, confermata INTEGER NOT NULL DEFAULT 0 CHECK (confermata IN (0, 1)));
CREATE TABLE au_val (
  au_id INTEGER NOT NULL REFERENCES au(id),
  val_id INTEGER NOT NULL REFERENCES val(id), campo TEXT,
  PRIMARY KEY (au_id, val_id)
);
CREATE TABLE ac_val (
  ac_id INTEGER NOT NULL REFERENCES ac(id),
  val_id INTEGER NOT NULL REFERENCES val(id), campo TEXT,
  PRIMARY KEY (ac_id, val_id)
);
CREATE TABLE IF NOT EXISTS "sedi" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                nome TEXT NOT NULL UNIQUE COLLATE NOCASE,
                campo TEXT NOT NULL CHECK (campo IN ('SA', 'SS'))
            , citta TEXT, lat REAL, lon REAL, posizione_di_prova INTEGER NOT NULL DEFAULT 0);
CREATE TABLE congiunte (
                au_id INTEGER NOT NULL UNIQUE REFERENCES au(id),
                ac_id INTEGER NOT NULL UNIQUE REFERENCES ac(id),
                PRIMARY KEY (au_id, ac_id)
            );
CREATE TABLE ulss (
                id INTEGER PRIMARY KEY,
                nome TEXT NOT NULL,
                citta TEXT NOT NULL,
                lat REAL NOT NULL,
                lon REAL NOT NULL
            );
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
PRAGMA writable_schema=OFF;
COMMIT;
